#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 9 + 2; std::vector<int> perm(n); std::iota(perm.begin(), perm.end(), 1); std::shuffle(perm.begin(), perm.end(), r); std::vector<std::vector<int>> seg; for (int x : perm) seg.push_back({x}); printf("%d\n", n); while (seg.size() > 1) { int i = r() % (seg.size() - 1); int x = seg[i][r() % seg[i].size()], y = seg[i + 1][r() % seg[i + 1].size()]; if (r() % 2) printf("%d %d\n", x, y); else printf("%d %d\n", y, x); seg[i].insert(seg[i].end(), seg[i + 1].begin(), seg[i + 1].end()); seg.erase(seg.begin() + i + 1); } }
